metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "de"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "event",
        "text": "main()"
      },
      "body": [
        {
          "id": "b1",
          "kind": "process",
          "text": "a = [5, 8, 6, 3, 2, 7, 2, 6]"
        },
        {
          "id": "b2",
          "kind": "process",
          "text": "n = len(a)"
        },
        {
          "id": "b3",
          "kind": "process",
          "text": "tree = [0] * (4 * n)    # die Kinder von Knoten k sind 2k und 2k + 1"
        },
        {
          "id": "b4",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d2"
          },
          "args": "1, 0, n - 1",
          "result": ""
        },
        {
          "id": "b5",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d3"
          },
          "args": "1, 0, n - 1, 2, 5",
          "result": "s"
        },
        {
          "id": "b6",
          "kind": "process",
          "text": "print(s)    # 18"
        },
        {
          "id": "b7",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d4"
          },
          "args": "1, 0, n - 1, 3, 10",
          "result": ""
        },
        {
          "id": "b8",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d3"
          },
          "args": "1, 0, n - 1, 2, 5",
          "result": "s"
        },
        {
          "id": "b9",
          "kind": "process",
          "text": "print(s)    # 25"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "build(node, lo, hi)"
      },
      "body": [
        {
          "id": "b10",
          "kind": "if",
          "text": "lo == hi",
          "yes": {
            "id": "r1",
            "body": [
              {
                "id": "b11",
                "kind": "process",
                "text": "tree[node] = a[lo]"
              }
            ]
          },
          "no": {
            "id": "r2",
            "body": [
              {
                "id": "b12",
                "kind": "process",
                "text": "mid = (lo + hi) // 2"
              },
              {
                "id": "b13",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d2"
                },
                "args": "2 * node, lo, mid",
                "result": ""
              },
              {
                "id": "b14",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d2"
                },
                "args": "2 * node + 1, mid + 1, hi",
                "result": ""
              },
              {
                "id": "b15",
                "kind": "process",
                "text": "tree[node] = tree[2 * node] + tree[2 * node + 1]"
              }
            ]
          }
        }
      ]
    },
    {
      "id": "d3",
      "head": {
        "kind": "method",
        "text": "query(node, lo, hi, l, r)"
      },
      "body": [
        {
          "id": "b16",
          "kind": "if",
          "text": "r < lo or hi < l",
          "yes": {
            "id": "r3",
            "body": [
              {
                "id": "b17",
                "kind": "exit",
                "text": "return 0    # keine Überlappung"
              }
            ]
          },
          "no": {
            "id": "r4",
            "body": [
              {
                "id": "b18",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b19",
          "kind": "if",
          "text": "l <= lo and hi <= r",
          "yes": {
            "id": "r5",
            "body": [
              {
                "id": "b20",
                "kind": "exit",
                "text": "return tree[node]    # ganz im Bereich"
              }
            ]
          },
          "no": {
            "id": "r6",
            "body": [
              {
                "id": "b21",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b22",
          "kind": "process",
          "text": "mid = (lo + hi) // 2"
        },
        {
          "id": "b23",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d3"
          },
          "args": "2 * node, lo, mid, l, r",
          "result": "left"
        },
        {
          "id": "b24",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d3"
          },
          "args": "2 * node + 1, mid + 1, hi, l, r",
          "result": "right"
        },
        {
          "id": "b25",
          "kind": "process",
          "text": "return left + right"
        }
      ]
    },
    {
      "id": "d4",
      "head": {
        "kind": "method",
        "text": "update(node, lo, hi, i, x)"
      },
      "body": [
        {
          "id": "b26",
          "kind": "if",
          "text": "lo == hi",
          "yes": {
            "id": "r7",
            "body": [
              {
                "id": "b27",
                "kind": "process",
                "text": "tree[node] = x"
              }
            ]
          },
          "no": {
            "id": "r8",
            "body": [
              {
                "id": "b28",
                "kind": "process",
                "text": "mid = (lo + hi) // 2"
              },
              {
                "id": "b29",
                "kind": "if",
                "text": "i <= mid",
                "yes": {
                  "id": "r9",
                  "body": [
                    {
                      "id": "b30",
                      "kind": "call",
                      "target": {
                        "kind": "local",
                        "diagram": "d4"
                      },
                      "args": "2 * node, lo, mid, i, x",
                      "result": ""
                    }
                  ]
                },
                "no": {
                  "id": "r10",
                  "body": [
                    {
                      "id": "b31",
                      "kind": "call",
                      "target": {
                        "kind": "local",
                        "diagram": "d4"
                      },
                      "args": "2 * node + 1, mid + 1, hi, i, x",
                      "result": ""
                    }
                  ]
                }
              },
              {
                "id": "b32",
                "kind": "process",
                "text": "tree[node] = tree[2 * node] + tree[2 * node + 1]"
              }
            ]
          }
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
